  case Active =>
    if event == "complete" {
      next := Completed;
    } else if event == "fail" {
      next := Failed;
    } else {
      next := Active;
    }
  case Completed =>
    if event == "reset" {
      next := Idle;
    } else {
      next := Completed;
    }
  case Failed =>
    if event == "reset" {
      next := Idle;
    } else {
      next := Failed;
    }
